nextflow_process {

    name "Test Process HUMID"
    script "../main.nf"
    config "./nextflow.config"
    process "HUMID"

    tag "modules"
    tag "modules_nfcore"
    tag "humid"
    tag "fastp"

    test("sarscov2 - paired-end") {

        setup {
            run("FASTP") {
                script "../../fastp/main.nf"
                process {
                    """
                    input[0] = channel.of([
                        [ id:'test', single_end:false ],
                        [
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                            file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                        ],
                        []
                    ])
                    input[1] = false
                    input[2] = false
                    input[3] = false
                    """
                }
            }
        }

        when {
            params {
                fastp_args = "--umi --umi_loc=per_read --umi_len=8"
                humid_args = "-s -a"
            }
            process {
                """
                input[0] = FASTP.out.reads
                input[1] = [[:],[]]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys:["log"])).match() },
                { assert path(process.out.log.get(0).get(1)).text.contains("Reading data... done.") },
            )
        }

    }

    test("sarscov2 - paired-end - stub") {

        options "-stub"

        when {
            params {
                fastp_args = "--umi --umi_loc=per_read --umi_len=8"
                humid_args = "-s -a"
            }
            process {
                """
                input[0] = channel.of([
                    [ id:'test', single_end:false ],
                    [
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true),
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_2.fastq.gz', checkIfExists: true)
                    ]
                ])
                input[1] = [[:],[]]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }


    test("sarscov2 - single-end") {

        setup {
            run("FASTP") {
                script "../../fastp/main.nf"
                process {
                    """
                    input[0] = channel.of([
                        [ id:'test', single_end:true ],
                        [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/fastq/test_1.fastq.gz', checkIfExists: true)],
                        []
                    ])
                    input[1] = false
                    input[2] = false
                    input[3] = false
                    """
                }
            }
        }

        when {
            params {
                fastp_args = "--umi --umi_loc=per_read --umi_len=8"
                humid_args = "-s -a"
            }
            process {
                """
                input[0] = FASTP.out.reads
                input[1] = [[:],[]]
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys:["log"])).match() },
                { assert path(process.out.log.get(0).get(1)).text.contains("Reading data... done.") },
            )
        }
    }

}

